def run(label,cmd):
 p=subprocess.run(cmd,cwd=r,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=90);(r/(label+'.log')).write_bytes(p.stdout);result['commands'].append({'label':label,'command':cmd,'exit':p.returncode,'log_sha256':hashlib.sha256(p.stdout).hexdigest()});print(label,p.returncode,p.stdout.decode(errors='replace')[-3500:],flush=True);return p
