 a=run(cc+'-control',[cc,*flags,'/c',str(control),'/Fo'+str(r/(cc+'-control.obj'))])
 b=run(cc+'-production',[cc,*flags,'/c',str(r/'src/modelnet/erasure_store.cpp'),'/Fo'+str(r/(cc+'-production.obj'))])
 text=b.stdout.decode(errors='replace')
 if a.returncode!=0 or b.returncode==0 or 'unistd.h' not in text:errors.append(cc+' unexpected control/diagnostic')
